insert into public.sentences (text, text_zh, notebook_id) values ('Since Plato, Western thought and the theory of knowledge have focused on the notions of True-False; as commendable as it was, it is high time to shift the concern to Robust-Fragile, and social epistemology to the more serious problem of Sucker-Nonsucker.', '自柏拉图以来，西方思想与知识论都聚焦于“真—假”。这固然值得称赞，但现在是时候把关注点转向“稳健—脆弱”，并把社会认识论的焦点放在更严肃的“受骗者—不受骗者”问题上。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('The problem of knowledge is that there are many more books on birds written by ornithologists than books on birds written by birds and books on ornithologists written by birds.', '知识的问题在于，关于鸟的书由鸟类学家写的远多于由“鸟”写的，至于由“鸟”写的关于鸟类学家的书就更少了。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('The perfect sucker understands that pigs can stare at pearls but doesn''t realize he can be in an analog situation.', '完美的冤大头知道“猪也会盯着珍珠看”，却没意识到自己可能处在同样的处境。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('It takes extraordinary wisdom and self-control to accept that many things have a logic we do not understand that is smarter than our own.', '承认许多事物遵循一种我们不理解、却比我们更聪明的逻辑，需要非凡的智慧与自制。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('Knowledge is subtractive, not additivewhat we subtract (reduction by what does not work, what not to do), not what we add (what to do).', '知识是减法而非加法——靠剔除无效之物与不该做的事，而非不断添加要做的事。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('They think that intelligence is about noticing things that are relevant (detecting patterns); in a complex world, intelligence consists in ignoring things that are irrelevant (avoiding false patterns).', '他们以为智力在于发现相关事物（识别模式）；在复杂世界里，智力在于忽略不相关事物（避免伪模式）。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('Happiness; we don''t know what it means, how to measure it, or how to reach it, but we know extremely well how to avoid unhappiness.', '幸福：我们不知道它究竟意味着什么、如何衡量、如何到达，但我们非常清楚如何避免“不幸”。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('The imagination of the genius vastly surpasses his intellect; the intellect of the academic vastly surpasses his imagination.', '天才的想象远超他的智性；学者的智性远超他的想象。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('The ideal trivium education, and the least harmful one to society and pupils, would be mathematics, logic, and Latin; a double dose of Latin authors to compensate for the severe loss of wisdom that comes from mathematics; just enough mathematics and logic to control verbiage and rhetoric.', '理想的“三艺”教育，也是对社会与学生伤害最小的，是数学、逻辑与拉丁文；多读一倍的拉丁作家，以弥补数学带来的智慧流失；数学与逻辑只需恰到好处，用来约束空话与修辞。', 36);
insert into public.sentences (text, text_zh, notebook_id) values ('The four most in;uential moderns: Darwin, Marx, Freud, and (the productive) Einstein were scholars but not academics. It has always been hard to do genuineand nonperishablework within institutions.', '现代最具影响力的四人——达尔文、马克思、弗洛伊德与（产出丰厚的）爱因斯坦——是学者而非学院派。在体制内做真正且不易腐朽的工作，一向艰难。', 36);
